FamilyTree.person({"id":"livina_stockman","name":"Livina Stockman","dates":"~1688 – 1744 Evergem","confidence":"sup","surname":"Stockman","family":"stockman","born":"~1688","died":"1744 Evergem","branch":"Bundervoet","line":"bundervoet","spouses":[{"id":"joannes_b","name":"Joannes Bundervoet"}],"source":"paulderidder; glorieuxp","note":"Source detail: Geneanet trees glorieuxp & paulderidder (both give her as c.1688-1744)\n\nJoannes Bundervoet's FIRST wife and mother of Christoffel (1709) and Pieter (1727). She died in 1744; Joannes then remarried Livina (Joanna) De Wilde ~1745 — the remarriage confirmed independently by the glorieuxp and paulderidder trees, and consistent with the chronology (Christoffel's 1709 birth predates the De Wilde marriage). Several other trees wrongly list Christoffel's mother as De Wilde."});
