FamilyTree.person({"id":"roland","name":"Roland De Keyser","dates":"1943 Tottenham – 2003","confidence":"fam","surname":"De Keyser","family":"dekeyser","born":"1943 Tottenham","died":"2003","branch":"DeKeyser","line":"de-keyser","father":"gustaaf","mother":"simonne","spouses":[{"id":"huguette","name":"Huguette Devriendt"}],"source":"Geneanet; The family itself","note":"Born in Tottenham, London in 1943 while his family were WWII refugees (Tottenham was then in the Edmonton registration district); an English registrar mis-wrote the Flemish name. Buried at Stene, Oostende. His 1943 London birth certificate is the key record to confirm his father Gustaaf and mother Simonne Vandewalle — and, if his father died in the war, Simonne likely returned to Oostende a widow with Roland and his sister."});
